import { test, expect } from '@playwright/test';

test.describe('Mobile Landscape Orientation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display app correctly in landscape orientation on mobile', async ({ page }) => {
    // Set viewport to mobile landscape
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify app container is visible
    const appContainer = page.getByRole('main');
    await expect(appContainer).toBeVisible();

    // Verify navigation menu is visible and accessible
    const navMenu = page.getByRole('navigation');
    await expect(navMenu).toBeVisible();

    // Verify logo is visible and correctly positioned
    const logo = page.getByRole('img', { name: /logo/i });
    await expect(logo).toBeVisible();

    // Verify user profile section is visible
    const userProfile = page.getByRole('region', { name: /user profile/i });
    await expect(userProfile).toBeVisible();

    // Verify search bar is visible and functional
    const searchBar = page.getByRole('search');
    await expect(searchBar).toBeVisible();

    // Verify search results are visible
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    // Verify footer is visible
    const footer = page.getByRole('contentinfo');
    await expect(footer).toBeVisible();

    // Verify app is responsive and not overflowing
    await expect(page).toHaveResponsiveDimensions();
  });

  test('should handle orientation change to portrait on mobile', async ({ page }) => {
    // Set viewport to mobile portrait
    await page.setViewportSize({ width: 375, height: 600 });

    // Verify app container is still visible
    const appContainer = page.getByRole('main');
    await expect(appContainer).toBeVisible();

    // Verify navigation menu is still visible
    const navMenu = page.getByRole('navigation');
    await expect(navMenu).toBeVisible();

    // Verify logo is still visible and correctly positioned
    const logo = page.getByRole('img', { name: /logo/i });
    await expect(logo).toBeVisible();

    // Verify user profile section is still visible
    const userProfile = page.getByRole('region', { name: /user profile/i });
    await expect(userProfile).toBeVisible();

    // Verify search bar is still visible and functional
    const searchBar = page.getByRole('search');
    await expect(searchBar).toBeVisible();

    // Verify search results are still visible
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    // Verify footer is still visible
    const footer = page.getByRole('contentinfo');
    await expect(footer).toBeVisible();

    // Verify app is responsive and not overflowing
    await expect(page).toHaveResponsiveDimensions();
  });
});
